// Circuits in the real window (ADR 0005): the application starts on the 7-segment circuit given by --circuit with
// firmware/src/counter.c, then circuits are selected and loaded from the page. The components are drawn by the
// rendering module of their type from the state computed by the electrical model in C++; the page decides nothing.
// window.sfFixtures is generated by tests/CMakeLists.txt from circuits/led-buttons.json and circuits/arduino-demo.json.
jasmine.getEnv().configure({random: false});

describe("Circuits", () => {
  const sf = () => window.siliconForge;
  const fixtures = window.sfFixtures;
  const element = (id) => document.getElementById(id);
  const display = () => document.querySelector(".bb-seven-segment");
  const rejection = async (promise) => {
    try { await promise; } catch (error) { return error; }
    throw new Error("the call did not reject");
  };
  const until = async (predicate, what, timeoutMs = 10000) => {
    const deadline = performance.now() + timeoutMs;
    while (!predicate()) {
      if (performance.now() > deadline) throw new Error(`timeout waiting for ${typeof what === "function" ? what() : what}`);
      await new Promise((resolve) => setTimeout(resolve, 20));
    }
  };
  /** Two frames after a pause: the second one covers no simulated time, so it carries present values, not averages. */
  const freeze = async () => {
    await sf().pause();
    const paused = (await sf().waitFor((state) => !state.running, 5000)).frame;
    await sf().waitFor((state) => state.frame >= paused + 2, 5000);
  };
  const choose = (id, name, content) => {
    const transfer = new DataTransfer();
    transfer.items.add(new File([content], name, {type: "application/json"}));
    element(id).files = transfer.files;
    element(id).dispatchEvent(new Event("change", {bubbles: true}));
  };

  beforeAll(async () => {
    await webFront.ready;
    await sf().waitFor((state) => state.mcu === "ATmega328P" && state.firmware === "counter.hex", 20000);
    await until(() => display() !== null, "the display of the circuit given on the command line", 20000);
  }, 40000);

  it("starts on the circuit of the command line and names the pins of its components", async () => {
    const circuit = await sf().circuit();
    expect(circuit.id).toBe("seven-segment");
    expect(circuit.name).toBe("7-segment counter");
    expect(element("circuit-select").value).toBe("seven-segment");
    expect(circuit.components.find((component) => component.id === "r-a").pin).toBe("D2");
    expect(circuit.components.find((component) => component.id === "display").properties.forwardVoltage).toBe(2);
    expect(await sf().circuits()).toEqual(jasmine.arrayContaining(["arduino-demo", "led-buttons", "seven-segment"]));
    expect(document.querySelectorAll("#breadboard .bb-resistor").length).toBe(8);
  });

  it("shows on the 7-segment display each digit the firmware counts", async () => {
    await sf().reset();
    await sf().setSpeed(2);
    await sf().run();
    const seen = [];
    let sent = 0;
    for (let round = 0; round < 5; ++round) {
      // Freeze the emulation once one more digit was sent, wherever it then is: the display is compared with what the
      // firmware says it shows. The firmware lights a digit, then sends it: frozen in the 3 ms of that transmission,
      // the display is already one digit ahead of the serial output.
      await sf().waitFor(() => (sf().output.match(/\d\r\n/g) ?? []).length > sent, 10000);
      await freeze();
      const lines = sf().output.match(/\d\r\n/g);
      sent = lines.length;
      const last = Number(lines.at(-1)[0]);
      const shown = Number(display().dataset.digit);
      expect(display().dataset.digit).toMatch(/^[0-9]$/);
      expect([last, (last + 1) % 10]).toContain(shown);
      expect(display().dataset.point).toBe(String(shown % 2 === 1));
      expect(sf().component("display")["a.brightness"]).toBe(shown === 1 || shown === 4 ? 0 : 1);
      seen.push({shown, last});
      await sf().run();
    }
    await sf().pause();
    expect(seen.filter(({shown, last}) => shown === last).length).toBeGreaterThanOrEqual(4, JSON.stringify(seen));
    expect(new Set(seen.map(({shown}) => shown)).size).toBeGreaterThanOrEqual(4, JSON.stringify(seen));
  }, 60000);

  it("decodes the serial frames of D1 in the logic analyser", async () => {
    await sf().instruments.sync();
    const decoded = sf().instruments.decodeUart("D1");
    expect(decoded.baud).toBe(9600);  // Found from the shortest pulse
    expect(decoded.text.startsWith("0\r\n1\r\n2\r\n")).toBe(true, `decoded ${JSON.stringify(decoded.text)}`);
    expect(decoded.bytes.every((byte) => byte.ok)).toBe(true, "a stop bit is low");
    expect(decoded.bytes[1].t - decoded.bytes[0].t).toBeCloseTo(10 / 9615.4, 6);  // UBRR0 = 103: 16 MHz / 16 / 104
    expect(sf().output.startsWith(decoded.text.slice(0, 9))).toBe(true, `serial monitor ${JSON.stringify(sf().output.slice(0, 12))}`);
  });

  it("refuses an interaction the component does not have, with a typed error", async () => {
    const unknown = await rejection(sf().setComponent("no-such-part", "pressed", 1));
    expect(unknown.code).toBe("siliconforge.unknownComponent");
    const readOnly = await rejection(sf().setComponent("display", "a.brightness", 1));
    expect(readOnly.code).toBe("siliconforge.invalidValue");
    expect(readOnly.message).toContain("read-only");
  });

  it("moves a dipole with the pointer, within the limits of its type", async () => {
    const board = document.querySelector("#breadboard svg");
    const resistor = () => document.querySelector('#breadboard [data-id="r-a"]');
    const centre = (target) => {
      const box = target.getBoundingClientRect();
      return {clientX: box.x + box.width / 2, clientY: box.y + box.height / 2};
    };
    const pointer = (target, type, at) => target.dispatchEvent(new PointerEvent(type, {bubbles: true, button: 0, pointerId: 7, ...at}));
    // A click outlines the resistor and puts a square on each of its ends, with its limits.
    const body = centre(resistor().querySelector(".bb-resistor-body"));
    pointer(resistor().querySelector(".bb-resistor-body"), "pointerdown", body);
    pointer(board, "pointerup", body);
    expect(resistor().classList).toContain("bb-selected");
    expect(document.querySelectorAll("#breadboard .bb-handle").length).toBe(2);
    expect(document.querySelector("#breadboard .bb-limits").textContent).toBe("Resistor · 11 holes (2–12)");
    // Dragging its b end far to the right stretches it to its maximum length only (12 holes), in its row.
    const end = document.querySelector('#breadboard .bb-handle[data-terminal="b"]');
    const from = centre(end);
    pointer(end, "pointerdown", from);
    for (let step = 1; step <= 6; ++step) pointer(board, "pointermove", {clientX: from.clientX + step * 40, clientY: from.clientY + step * 4});
    pointer(board, "pointerup", {clientX: from.clientX + 240, clientY: from.clientY + 24});
    await until(() => resistor()?.classList.contains("bb-selected") && document.querySelector("#breadboard .bb-limits")?.textContent.includes("12 holes"),
                "the stretched resistor, still outlined after the board is redrawn");
    expect((await sf().circuit()).components.find((component) => component.id === "r-a").at).toEqual({a: "h22", b: "h34"});
    // The model checks the limits too.
    const tooLong = await rejection(sf().moveComponent("r-a", {b: "h36"}));
    expect(tooLong.code).toBe("siliconforge.invalidPlacement");
    expect(tooLong.message).toContain("14 holes apart");
    // Escape lets it go.
    document.body.dispatchEvent(new KeyboardEvent("keydown", {key: "Escape", bubbles: true}));
    expect(document.querySelector("#breadboard .bb-selected")).toBeNull();
  });

  it("loads an example: another circuit, its firmware, and buttons that light the LED", async () => {
    await sf().loadExample("buttons");
    await sf().waitFor((state) => state.firmware === "buttons.hex" && state.running, 5000);
    await until(() => document.querySelector('.bb-led[data-pin="D9"]') !== null, "the LED of the new circuit");
    expect(display()).toBeNull();
    expect(element("circuit-select").value).toBe("led-buttons");
    expect(element("circuit-name").textContent).toBe("LED and two buttons");
    const led = () => Number(document.querySelector('.bb-led[data-pin="D9"]').dataset.level);
    await sf().waitForPin("D2", sf().pinState.high, 10000);  // The firmware enabled the pull-up
    expect(led()).toBe(0);

    const hold = document.querySelector('.bb-button[data-pin="D2"]');
    hold.dispatchEvent(new PointerEvent("pointerdown", {bubbles: true}));
    await sf().waitFor(() => led() === 1, 10000);
    expect(sf().pin("D2").state).toBe(sf().pinState.low);
    expect(sf().component("button-d2").pressed).toBe(true);
    hold.dispatchEvent(new PointerEvent("pointerup", {bubbles: true}));
    await sf().waitFor(() => led() === 0, 10000);

    const latch = document.querySelector('.bb-button[data-pin="D3"]');
    latch.dispatchEvent(new PointerEvent("pointerdown", {bubbles: true}));
    await sf().waitFor(() => led() === 1, 10000);
    latch.dispatchEvent(new PointerEvent("pointerup", {bubbles: true}));
    await new Promise((resolve) => setTimeout(resolve, 200));
    expect(led()).toBe(1);  // Latched by the firmware
  }, 40000);

  it("loads a circuit chosen with the file input, keeping the firmware of the same MCU", async () => {
    choose("circuit-file", "mine.json", JSON.stringify({...fixtures.circuit, name: "My own circuit"}));
    await until(() => element("circuit-name").textContent === "My own circuit", "the loaded circuit");
    expect(element("circuit-error").hidden).toBe(true);
    expect(element("circuit-select").selectedOptions[0].textContent).toBe("My own circuit (loaded)");
    expect(sf().state.firmware).toBe("buttons.hex");
    expect((await sf().circuit()).id).toBe("mine.json");
  });

  it("reports an invalid circuit with its JSON path and keeps the current one", async () => {
    const broken = structuredClone(fixtures.circuit);
    broken.components[1].properties.resistance = -5;
    choose("circuit-file", "broken.json", JSON.stringify(broken));
    await until(() => !element("circuit-error").hidden, "the circuit error");
    expect(element("circuit-error").textContent).toContain("Cannot load broken.json");
    expect(element("circuit-error").textContent).toContain("/components/1/properties/resistance");
    expect(element("circuit-name").textContent).toBe("My own circuit");

    const invalid = await rejection(sf().loadCircuit("broken.json", JSON.stringify(broken)));
    expect(invalid.code).toBe("siliconforge.invalidCircuit");
    expect(invalid.message.startsWith("/components/1/properties/resistance: ")).toBe(true);
    const tooFar = await rejection(sf().loadCircuit("far.json", JSON.stringify({...fixtures.circuit, chip: {mcu: "atmega328p", column: 25}, components: [], wires: []})));
    expect(tooFar.code).toBe("siliconforge.invalidCircuit");
    expect(tooFar.message.startsWith("/chip/column: ")).toBe(true);
    const unknown = await rejection(sf().selectCircuit("no-such-circuit"));
    expect(unknown.code).toBe("siliconforge.unknownCircuit");
    expect((await sf().circuit()).id).toBe("mine.json");
  });

  it("signals a short circuit between an output and a rail", async () => {
    await sf().loadExample("blink");
    expect(element("shorts").hidden).toBe(true);
    const shorted = structuredClone(fixtures.demo);
    shorted.wires.push({from: "g15", to: "T-15", color: "white"});  // D13 straight to ground
    await sf().loadCircuit("shorted.json", JSON.stringify(shorted));
    await sf().waitFor((state) => state.shorts.length === 1, 5000);  // As soon as the firmware drives D13 high
    await until(() => !element("shorts").hidden, "the short-circuit banner");
    expect(element("shorts").textContent).toContain("D13");
    expect(element("shorts").textContent).toContain("ground rail");
    await sf().selectCircuit("arduino-demo");
    await sf().waitFor((state) => state.shorts.length === 0, 5000);
    await until(() => element("shorts").hidden, "the banner to clear");
  }, 40000);

  it("leaves a bare board to a microcontroller the circuit was not made for", async () => {
    await sf().loadMcu(JSON.stringify({...fixtures.mcu, name: "Another chip"}));
    await sf().waitFor((state) => state.mcu === "Another chip", 5000);
    await until(() => document.querySelector("#breadboard .bb-chip-name")?.textContent === "another chip", "the bare board");
    expect(await sf().circuit()).toBeNull();
    expect(document.querySelectorAll("#breadboard .bb-led, #breadboard .bb-wire").length).toBe(0);
    expect(document.querySelectorAll("#breadboard .bb-leg.bb-io").length).toBeGreaterThan(20);
    await sf().selectMcu("atmega328p");
    await until(() => document.querySelector('#breadboard .bb-led[data-pin="D13"]') !== null, "the circuit to come back with its MCU");
  }, 40000);
  it("draws the screen of the SPI display example", async () => {
    await sf().loadExample("tft_spi");
    await sf().waitFor((state) => state.components?.tft?.pixelsWritten === 9600, 20000);
    const visible = () => document.querySelector('#breadboard .bb-tft-panel image[visibility="visible"]');
    const read = async () => {
      const href = visible()?.getAttribute("href");
      if (!href) return null;
      const bitmap = await createImageBitmap(await (await fetch(href)).blob());
      const canvas = document.createElement("canvas");
      canvas.width = bitmap.width; canvas.height = bitmap.height;
      const context = canvas.getContext("2d");
      context.drawImage(bitmap, 0, 0);
      return (x, y) => Array.from(context.getImageData(x, y, 1, 1).data.slice(0, 3));
    };
    let at;
    const deadline = performance.now() + 15000;
    for (;;) {
      at = await read();
      if (at && at(180, 90)[0] > 200 && Math.min(...at(140, 150)) > 200) break;  // The first and the last quadrants painted
      if (performance.now() > deadline) throw new Error("timeout waiting for the painted window in the panel image");
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
    const connectors = Array.from(document.querySelectorAll("#breadboard .bb-tft-pad"));
    expect(connectors.length).toBe(9);
    const fill = (name) => connectors.find((c) => c.dataset.terminal === name).getAttribute("fill");
    // The colours of the wires plugged in the strips of the header holes: VCC and LED to the +5 V rail, GND to ground, then the signals
    expect(fill("vcc")).toBe("#d8312b"); expect(fill("gnd")).toBe("#2b2b2b");
    expect(fill("cs")).toBe("#ec7a1c"); expect(fill("reset")).toBe("#e8c51c"); expect(fill("dc")).toBe("#2fa84f");
    expect(fill("sdi")).toBe("#2f6fd8"); expect(fill("sck")).toBe("#e8e8e8"); expect(fill("led")).toBe("#d8312b");
    const pinOf = (name) => connectors.find((c) => c.dataset.terminal === name).dataset.pin;
    // What each terminal is wired to on the chip, followed through the jumper wires
    expect([pinOf("cs"), pinOf("reset"), pinOf("dc"), pinOf("sdi"), pinOf("sck")]).toEqual(["D10", "D8", "D9", "D11", "D13"]);
    expect(pinOf("vcc")).toBe("");
    expect(document.querySelector("#breadboard svg.breadboard").lastElementChild.classList.contains("bb-plates")).toBe(true);  // In front of the chip and the probes
    expect(document.querySelectorAll("#breadboard .bb-plates .bb-tft-leads path").length).toBe(18);  // A lead (outline and core) per terminal
    const frame = visible().getBoundingClientRect();
    expect(frame.width).toBeGreaterThan(frame.height);  // Landscape
    const [, viewTop] = document.querySelector("#breadboard svg.breadboard").getAttribute("viewBox").split(" ").map(Number);
    expect(Number(visible().getAttribute("y"))).toBeGreaterThanOrEqual(viewTop);  // Not cut off above the board
    expect(at(10, 10)).toEqual([0, 0, 0]);          // Outside the painted window
    // The 240 x 320 memory is shown in landscape (a quarter turn): its top-left quadrant is at the top right, its bottom-right one at the bottom left
    const red = at(180, 90), white = at(140, 150);
    expect(red[0]).toBeGreaterThan(200); expect(red[1]).toBeLessThan(40); expect(red[2]).toBeLessThan(40);
    expect(Math.min(...white)).toBeGreaterThan(200);
  }, 40000);
  it("shows the text of the character LCD example dot by dot", async () => {
    await sf().loadExample("lcd1602");
    await sf().run();
    const module = () => document.querySelector('#breadboard .bb-lcd-module[data-component="lcd"]');
    await until(() => module()?.dataset.text?.startsWith("Hello, world!"), () => `the greeting on the LCD (${JSON.stringify(module()?.dataset.text)})`, 20000);
    const state = sf().component("lcd");
    expect(state.early).toBe(0);
    expect(state.timing).toBe(0);
    expect(state.dataBits).toBe(4);
    expect(state.reads).toBeGreaterThan(0);  // The firmware polls the busy flag
    expect(module().dataset.text.split("\n")[1]).toMatch(/^Seconds: \d+/);
    expect(Number(module().dataset.contrast)).toBe(1);
    expect(Number(module().dataset.backlight)).toBeGreaterThan(0.9);
    // The dots that are on: the 13 characters of the greeting and the heart, then the counter
    const ink = module().querySelectorAll("path")[1].getAttribute("d");
    expect(ink.split("M").length).toBeGreaterThan(200);
    const pads = Array.from(module().querySelectorAll(".bb-lcd-pad"));
    expect(pads.length).toBe(16);
    const pinOf = (name) => pads.find((pad) => pad.dataset.terminal === name).dataset.pin;
    expect([pinOf("rs"), pinOf("rw"), pinOf("e"), pinOf("d4"), pinOf("d7")]).toEqual(["D8", "D9", "D10", "D4", "D7"]);
    expect(pinOf("d0")).toBe("");
    await sf().pause();
  }, 40000);
  it("shows the text of the character LCD driven over I2C", async () => {
    await sf().loadExample("lcd1602_i2c");
    await sf().run();
    const module = () => document.querySelector('#breadboard .bb-lcd-module[data-component="lcd"]');
    await until(() => module()?.dataset.text?.startsWith("Hello over I2C!"), () => `the greeting on the LCD (${JSON.stringify(module()?.dataset.text)})`, 20000);
    const state = sf().component("lcd");
    expect(state.early).toBe(0);
    expect(state.i2cReads).toBeGreaterThan(0);  // The busy flag, read through the PCF8574
    expect(state.backlight).toBe(1);
    const pads = Array.from(module().querySelectorAll(".bb-lcd-pad"));
    expect(pads.map((pad) => pad.dataset.terminal)).toEqual(["gnd", "vcc", "sda", "scl"]);
    expect(pads.map((pad) => pad.dataset.pin).slice(2)).toEqual(["A4", "A5"]);
    await sf().pause();
  }, 40000);
  it("sets the logic analyser to watch the display bus when the example loads", async () => {
    await sf().loadExample("tft_spi");
    const view = () => window.siliconForge.instruments.view;
    const names = () => window.siliconForge.instruments.channels().map((channel) => channel.pin);
    await until(() => view().trigger.single && !view().live && view().triggered !== null,
                () => `the single trigger on the display bus (${JSON.stringify({...view(), cursors: undefined})}, now ${window.siliconForge.instruments.now})`, 20000);
    expect(names().sort()).toEqual(["PB0", "PB1", "PB2", "PB3", "PB5"]);  // D8, D9, D10, D11, D13
    expect(view().span).toBeLessThan(0.0001);
    const dc = window.siliconForge.instruments.samples("PB1");
    expect(dc.t.some((t) => Math.abs(t - view().triggered) < 1e-9)).toBe(true);
  }, 40000);

  it("lets the user drag the display panel onto the board to keep the board at full size", async () => {
    try { localStorage.removeItem("siliconforge.plate.tft"); } catch { /* Storage may be unavailable */ }
    await sf().loadExample("tft_spi");
    await until(() => document.querySelector("#breadboard .bb-tft-panel") !== null, "the panel");
    const svgElement = () => document.querySelector("#breadboard svg.breadboard");
    const viewBox = () => svgElement().getAttribute("viewBox").split(" ").map(Number);
    expect(viewBox()[1]).toBeLessThan(0);  // Above the board: the view grew
    const panel = document.querySelector("#breadboard .bb-tft-panel");
    const box = panel.getBoundingClientRect();
    const from = {x: box.x + box.width / 2, y: box.y + box.height / 2};
    const unit = svgElement().getScreenCTM().a;
    const fire = (type, point) => panel.dispatchEvent(new PointerEvent(type, {bubbles: true, clientX: point.x, clientY: point.y, pointerId: 1, button: 0}));
    fire("pointerdown", from);
    fire("pointermove", {x: from.x + 10 * unit, y: from.y + 120 * unit});
    fire("pointerup", {x: from.x + 10 * unit, y: from.y + 120 * unit});
    expect(panel.getAttribute("transform")).toMatch(/^translate\(/);
    // The picture goes with the plate: it stays inside the frame the plate draws
    await until(() => panel.querySelector('image[visibility="visible"]') !== null, "the picture of the panel");
    const picture = panel.querySelector('image[visibility="visible"]').getBoundingClientRect();
    const outline = panel.querySelector("rect").getBoundingClientRect();
    expect(picture.left).toBeGreaterThanOrEqual(outline.left - 1); expect(picture.right).toBeLessThanOrEqual(outline.right + 1);
    expect(picture.top).toBeGreaterThanOrEqual(outline.top - 1); expect(picture.bottom).toBeLessThanOrEqual(outline.bottom + 1);
    expect(viewBox()[1]).toBeGreaterThan(-60);  // Mostly over the board now: the view shrinks back
    expect(JSON.parse(localStorage.getItem("siliconforge.plate.tft")).dy).toBeGreaterThan(100);
    // A new load remembers the position
    await sf().loadExample("tft_spi");
    await until(() => document.querySelector("#breadboard .bb-tft-panel")?.getAttribute("transform")?.startsWith("translate("), "the remembered position");
    try { localStorage.removeItem("siliconforge.plate.tft"); } catch { /* Storage may be unavailable */ }
  }, 40000);
});
